// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 _val) public {
        vm.assume(_val > 0);
        c.SetMinSum(_val);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        uint256 stored = c.MinSum();

        assertTrue(stored == _val);
    }
}
